1	/**
2	 * Shared-hosting account provisioner (Phase 1).
3	 *
4	 * ┌────────────────────────────────────────────────────────────────────────┐
5	 * │ SAFETY POSTURE — READ BEFORE ENABLING                                    │
6	 * │                                                                          │
7	 * │ This provisions UNTRUSTED customers side-by-side on ONE box. The         │
8	 * │ isolation shell (jailed user + per-user PHP-FPM pool + open_basedir +    │
9	 * │ disk quota + scoped DB + chrooted SFTP) is the standard Hestia/cPanel    │
10	 * │ model, but multi-tenant isolation is the one place a subtle gap is a     │
11	 * │ CROSS-CUSTOMER BREACH. So the whole provisioner is INERT unless          │
12	 * │ `ENABLE_SHARED_HOSTING=1` AND not SANDBOX. Do NOT flip that flag in      │
13	 * │ production until this has been (1) reviewed as a security change,        │
14	 * │ (2) validated end-to-end on a dedicated STAGING shared node,             │
15	 * │ (3) paired with fail2ban + ModSecurity + a malware scanner.             │
16	 * │                                                                          │
17	 * │ The sshd change (SFTP chroot) is `sshd -t`-validated BEFORE any reload,  │
18	 * │ so a bad config can never lock the box out — but it still deserves the   │
19	 * │ staging pass.                                                            │
20	 * └────────────────────────────────────────────────────────────────────────┘
21	 *
22	 * Everything a shell touches is validated through the tested pure helpers in
23	 * lib/hosting.ts BEFORE interpolation.
24	 */
25	
26	import { Client } from "ssh2";
27	import { randomBytes } from "node:crypto";
28	import { promises as dns } from "node:dns";
29	import { db } from "../lib/db";
30	import { SANDBOX } from "../lib/sandbox";
31	import { decryptSecret, encryptSecret } from "../lib/crypto-box";
32	import {
33	  isValidUnixUsername,
34	  isValidHostingDomain,
35	  planLimits,
36	  diskQuotaBlocks,
37	  accountPaths,
38	} from "../lib/hosting";
39	
40	const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
41	const CONNECT_TIMEOUT_MS = 20_000;
42	const STEP_TIMEOUT_MS = 60_000;
43	
44	/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
45	function strongPassword(len = 22): string {
46	  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
47	  const bytes = randomBytes(len);
48	  let out = "";
49	  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
50	  return out;
51	}
52	
53	async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
54	  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
55	  if (!password) throw new Error("Hosting node has no root credential on record.");
56	  const conn = new Client();
57	  await new Promise<void>((resolve, reject) => {
58	    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
59	    conn
60	      .on("ready", () => { clearTimeout(timer); resolve(); })
61	      .on("error", (e) => { clearTimeout(timer); reject(e); })
62	      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
63	  });
64	  return conn;
65	}
66	
67	function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
68	  return new Promise((resolve, reject) => {
69	    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
70	    conn.exec(command, (err, stream) => {
71	      if (err) { clearTimeout(timer); return reject(err); }
72	      let out = "";
73	      stream
74	        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
75	        .on("data", (d: Buffer) => { out += d.toString(); })
76	        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
77	    });
78	  });
79	}
80	
81	async function run(conn: Client, label: string, cmd: string): Promise<void> {
82	  const r = await exec(conn, cmd, STEP_TIMEOUT_MS);
83	  if (r.code !== 0) throw new Error(`${label} failed: ${r.out.slice(0, 300)}`);
84	}
85	
86	/**
87	 * The name-based nginx vhost for one account — HTTP-only until a cert exists, and
88	 * HTTP→HTTPS + a 443 SNI block once it does. Shared IP; routed purely by
89	 * server_name; PHP proxied to THIS account's socket only, root jailed to its
90	 * webroot. Pure string — no interpolation reaches a shell here.
91	 */
92	function renderHostingVhost(username: string, domain: string, webroot: string, sock: string, sslLiveDir: string | null): string {
93	  const phpLoc = [
94	    `    location ~ \\.php$ {`,
95	    `        include fastcgi_params;`,
96	    `        fastcgi_pass unix:${sock};`,
97	    `        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;`,
98	    `    }`,
99	  ].join("\n");
100	  const body = [
101	    `    root ${webroot};`,
102	    `    index index.php index.html;`,
103	    `    location / { try_files $uri $uri/ /index.php?$query_string; }`,
104	    phpLoc,
105	    `    location ~ /\\. { deny all; }`,
106	  ].join("\n");
107	  const http = [
108	    `server {`,
109	    `    listen 80;`,
110	    `    listen [::]:80;`,
111	    `    server_name ${domain} www.${domain};`,
112	    `    location ^~ /.well-known/acme-challenge/ { root /var/www/html; }`,
113	    sslLiveDir ? `    location / { return 301 https://$host$request_uri; }` : body,
114	    `}`,
115	  ].join("\n");
116	  if (!sslLiveDir) return http + "\n";
117	  const https = [
118	    `server {`,
119	    `    listen 443 ssl;`,
120	    `    listen [::]:443 ssl;`,
121	    `    server_name ${domain} www.${domain};`,
122	    `    ssl_certificate ${sslLiveDir}/fullchain.pem;`,
123	    `    ssl_certificate_key ${sslLiveDir}/privkey.pem;`,
124	    `    ssl_protocols TLSv1.2 TLSv1.3;`,
125	    body,
126	    `}`,
127	  ].join("\n");
128	  return `${http}\n${https}\n`;
129	}
130	
131	/** Write a vhost file + enable it, tested before reload. */
132	async function installVhost(conn: Client, username: string, conf: string): Promise<void> {
133	  const path = `/etc/nginx/sites-available/hosting-${username}.conf`;
134	  await run(conn, "write vhost", `cat > ${path} <<'VH'\n${conf}VH\nln -sfn ${path} /etc/nginx/sites-enabled/hosting-${username}.conf`);
135	  await run(conn, "test + reload nginx", `nginx -t && systemctl reload nginx`);
136	}
137	
138	/** The per-user PHP-FPM pool config (the PHP isolation boundary). Same socket
139	 *  path across versions, so the vhost never changes when PHP is switched. */
140	function fpmPoolConf(u: string, home: string, webroot: string): string {
141	  const sock = `/run/php/${u}.sock`;
142	  return [
143	    `[${u}]`, `user = ${u}`, `group = ${u}`, `listen = ${sock}`, `listen.owner = ${u}`, `listen.group = www-data`,
144	    `pm = ondemand`, `pm.max_children = 6`, `pm.process_idle_timeout = 30s`, `chdir = ${webroot}`,
145	    `php_admin_value[open_basedir] = ${home}:/tmp:/usr/share/php`,
146	    `php_admin_value[disable_functions] = exec,passthru,shell_exec,system,proc_open,popen,curl_multi_exec,parse_ini_file,show_source`,
147	    `php_admin_value[upload_tmp_dir] = ${home}/tmp`, `php_admin_value[session.save_path] = ${home}/tmp`,
148	  ].join("\n");
149	}
150	
151	/** Write + (re)load an account's FPM pool for a given PHP version. */
152	async function writeFpmPool(conn: Client, u: string, home: string, webroot: string, php: string): Promise<void> {
153	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
154	  await run(conn, "php-fpm pool", `cat > /etc/php/${php}/fpm/pool.d/${u}.conf <<'POOL'\n${fpmPoolConf(u, home, webroot)}\nPOOL\nsystemctl reload php${php}-fpm 2>/dev/null || systemctl restart php${php}-fpm`);
155	}
156	
157	/**
158	 * The isolation shell for one account (HTTP-only vhost; SSL added later by the
159	 * sweep once DNS points at us). Every interpolated value has already cleared a
160	 * validator, so nothing here can be a shell metacharacter.
161	 */
162	async function applyIsolation(
163	  conn: Client,
164	  a: { username: string; primaryDomain: string; diskQuotaMB: number; sftpPassword: string },
165	  php: string,
166	): Promise<void> {
167	  const u = a.username;
168	  const d = a.primaryDomain;
169	  if (!isValidUnixUsername(u)) throw new Error(`refusing unsafe username ${u}`);
170	  if (!isValidHostingDomain(d)) throw new Error(`refusing unsafe domain ${d}`);
171	  if (!/^\d\.\d$/.test(php)) throw new Error(`refusing unsafe php version ${php}`);
172	  const { home, webroot } = accountPaths(u);
173	  const hardBlocks = diskQuotaBlocks(Math.max(1, Math.round(a.diskQuotaMB / 1024)));
174	  const softBlocks = Math.floor(hardBlocks * 0.95);
175	  const sock = `/run/php/${u}.sock`;
176	
177	  // 1. Jailed user. Home is ROOT-owned (a chroot requirement); the user owns only
178	  //    public_html + tmp under it. nologin shell — SFTP-only via the chroot below.
179	  await run(conn, "create user", `id -u ${u} >/dev/null 2>&1 || useradd -m -d ${home} -s /usr/sbin/nologin ${u}`);
180	  await run(conn, "chroot-safe home", `chown root:root ${home} && chmod 755 ${home} && mkdir -p ${webroot} ${home}/tmp && chown ${u}:${u} ${webroot} ${home}/tmp && chmod 700 ${home}/tmp`);
181	  await run(conn, "sftp password", `printf '%s:%s' ${u} '${a.sftpPassword}' | chpasswd`);
182	
183	  // 2. Disk quota (fs must have usrquota — node onboarding enables it).
184	  await run(conn, "disk quota", `command -v setquota >/dev/null 2>&1 && setquota -u ${u} ${softBlocks} ${hardBlocks} 0 0 /home || echo 'quota tool absent — skipped'`);
185	
186	  // 3. Per-user PHP-FPM pool — THE PHP isolation boundary.
187	  await writeFpmPool(conn, u, home, webroot, php);
188	
189	  // 4. Name-based vhost (HTTP only for now).
190	  await installVhost(conn, u, renderHostingVhost(u, d, webroot, sock, null));
191	
192	  // 5. Chrooted SFTP — sshd -t GUARDED so a bad config can never lock out the box.
193	  const sftpConf = [
194	    `Match User ${u}`,
195	    `    ChrootDirectory ${home}`,
196	    `    ForceCommand internal-sftp`,
197	    `    AllowTcpForwarding no`,
198	    `    X11Forwarding no`,
199	  ].join("\n");
200	  const sshdFile = `/etc/ssh/sshd_config.d/nxeon-${u}.conf`;
201	  await run(
202	    conn,
203	    "sftp chroot (guarded)",
204	    // Write to a temp include, validate the WHOLE sshd config, and only then move
205	    // it into place + reload. If sshd -t fails, discard — never reload a broken config.
206	    `mkdir -p /etc/ssh/sshd_config.d && cat > ${sshdFile}.new <<'SSHD'\n${sftpConf}\nSSHD\n` +
207	      `cp -f ${sshdFile}.new ${sshdFile} && if sshd -t 2>/dev/null; then systemctl reload ssh 2>/dev/null || systemctl reload sshd; else rm -f ${sshdFile}; echo 'sshd -t rejected the chroot block — SFTP not enabled, box untouched'; fi; rm -f ${sshdFile}.new`,
208	  );
209	}
210	
211	// ---- DB provisioning (per-account, on demand) ------------------------------
212	
213	/** Create ONE scoped MySQL/MariaDB user+db on the account's node. */
214	async function provisionHostingDatabase(dbId: string): Promise<void> {
215	  const rec = await db.hostingDatabase.findUnique({ where: { id: dbId }, include: { account: { include: { node: true } } } });
216	  if (!rec || rec.status !== "PENDING") return;
217	  if (SANDBOX || !ENABLED) {
218	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: SANDBOX ? "ACTIVE" : "PENDING", passwordEnc: null, error: SANDBOX ? null : "Shared hosting not enabled." } });
219	    return;
220	  }
221	  const name = rec.name;
222	  const user = rec.dbUser;
223	  const pass = rec.passwordEnc ? decryptSecret(rec.passwordEnc) : "";
224	  // DB name + user were built from the validated username; re-assert shape.
225	  if (!/^[a-z0-9_]{1,64}$/.test(name) || !/^[a-z0-9_]{1,32}$/.test(user) || !pass) {
226	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: "invalid db identifiers" } });
227	    return;
228	  }
229	  try {
230	    const conn = await connectNode(rec.account.node);
231	    try {
232	      // Grants scoped to THIS database only — the data-isolation boundary.
233	      const sql = `CREATE DATABASE IF NOT EXISTS \\\`${name}\\\`; CREATE USER IF NOT EXISTS '${user}'@'localhost' IDENTIFIED BY '${pass}'; GRANT ALL PRIVILEGES ON \\\`${name}\\\`.* TO '${user}'@'localhost'; FLUSH PRIVILEGES;`;
234	      await run(conn, "create database", `mysql -e "${sql}"`);
235	    } finally {
236	      try { conn.end(); } catch { /* */ }
237	    }
238	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "ACTIVE", passwordEnc: null, error: null } });
239	  } catch (e) {
240	    await db.hostingDatabase.update({ where: { id: rec.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
241	  }
242	}
243	
244	export async function hostingDatabaseSweep(): Promise<void> {
245	  const pending = await db.hostingDatabase.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
246	  for (const p of pending) await provisionHostingDatabase(p.id).catch((e) => console.error(`[hosting] db ${p.id} failed`, e));
247	}
248	
249	// ---- Account provisioning --------------------------------------------------
250	
251	export async function provisionHostingAccount(accountId: string): Promise<void> {
252	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
253	  if (!account || account.status !== "PENDING") return;
254	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
255	
256	  if (SANDBOX || !ENABLED) {
257	    if (SANDBOX) {
258	      const pw = strongPassword();
259	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
260	    } else {
261	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
262	    }
263	    return;
264	  }
265	
266	  try {
267	    const allowed = planLimits(account.plan).phpVersions;
268	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
269	    const sftpPassword = strongPassword();
270	    const conn = await connectNode(account.node);
271	    try {
272	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
273	    } finally {
274	      try { conn.end(); } catch { /* */ }
275	    }
276	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
277	  } catch (e) {
278	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
279	  }
280	}
281	
282	export async function hostingProvisionSweep(): Promise<void> {
283	  const pending = await db.hostingAccount.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 10 });
284	  for (const p of pending) await provisionHostingAccount(p.id).catch((e) => console.error(`[hosting] provision ${p.id} failed`, e));
285	}
286	
287	// ---- SSL sweep (post-DNS, no sshd risk) ------------------------------------
288	
289	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
290	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
291	  try {
292	    const a = await dns.resolve4(domain);
293	    return a.includes(ip);
294	  } catch {
295	    return false;
296	  }
297	}
298	
299	/**
300	 * For each ACTIVE account without HTTPS, once its domain resolves to the node's
301	 * shared IP, issue a per-domain cert (webroot) and upgrade the vhost to a 443 SNI
302	 * block. Safe: touches only nginx + certbot, never sshd.
303	 */
304	export async function hostingSslSweep(): Promise<void> {
305	  if (SANDBOX || !ENABLED) return;
306	  const accts = await db.hostingAccount.findMany({
307	    where: { status: "ACTIVE", sslActive: false },
308	    include: { node: true },
309	    take: 20,
310	  });
311	  for (const a of accts) {
312	    try {
313	      if (!isValidHostingDomain(a.primaryDomain) || !isValidUnixUsername(a.username)) continue;
314	      if (!(await domainPointsAt(a.primaryDomain, a.node.publicIp))) continue; // DNS not pointed yet
315	      const d = a.primaryDomain;
316	      const conn = await connectNode(a.node);
317	      try {
318	        const issue = await exec(conn, `certbot certonly --webroot -w /var/www/html -d ${d} -d www.${d} --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`, 3 * 60_000);
319	        const liveDir = `/etc/letsencrypt/live/${d}`;
320	        const have = await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`);
321	        if (have.out.trim() !== "yes") { console.log(`[hosting] cert for ${d} not issued yet: ${issue.out.slice(0, 160)}`); continue; }
322	        const { webroot } = accountPaths(a.username);
323	        await installVhost(conn, a.username, renderHostingVhost(a.username, d, webroot, `/run/php/${a.username}.sock`, liveDir));
324	      } finally {
325	        try { conn.end(); } catch { /* */ }
326	      }
327	      await db.hostingAccount.update({ where: { id: a.id }, data: { sslActive: true } });
328	      console.log(`[hosting] HTTPS active for ${a.primaryDomain}`);
329	    } catch (e) {
330	      console.error(`[hosting] ssl sweep ${a.id} failed`, e);
331	    }
332	  }
333	}
334	
335	// ---- Panel task queue (PHP switch, WordPress, backup, restore) -------------
336	
337	const SAFE_ID = /^[a-z0-9_]{1,64}$/;
338	const SAFE_EMAIL = /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9.-]{1,190}\.[A-Za-z]{2,24}$/;
339	
340	async function failTask(id: string, msg: string): Promise<void> {
341	  await db.hostingTask.update({ where: { id }, data: { status: "FAILED", error: msg } }).catch(() => undefined);
342	}
343	
344	/** Move an account's FPM pool to a new PHP version (socket path is unchanged, so
345	 *  the vhost never needs editing). */
346	async function taskPhpSwitch(conn: Client, a: { id: string; username: string; phpVersion: string }, payload: string | null): Promise<void> {
347	  const version = String(JSON.parse(payload || "{}").version ?? "");
348	  if (!/^\d\.\d$/.test(version)) throw new Error("invalid php version");
349	  const { home, webroot } = accountPaths(a.username);
350	  if (version !== a.phpVersion) {
351	    await run(conn, "remove old pool", `rm -f /etc/php/${a.phpVersion}/fpm/pool.d/${a.username}.conf; systemctl reload php${a.phpVersion}-fpm 2>/dev/null || true`);
352	  }
353	  await writeFpmPool(conn, a.username, home, webroot, version);
354	  await db.hostingAccount.update({ where: { id: a.id }, data: { phpVersion: version } });
355	}
356	
357	/** One-click WordPress: create the DB, drop WordPress in the webroot, install it
358	 *  as the jailed account user via WP-CLI. Returns the admin login (shown once). */
359	/** Re-check the plan DB cap at DB-creation time. The worker processes tasks
360	 *  SEQUENTIALLY, so this is the serialization point that closes the TOCTOU race
361	 *  the action-level gate can't (audit 2026-08-01). */
362	async function assertDbCap(accountId: string, maxDatabases: number): Promise<void> {
363	  const n = await db.hostingDatabase.count({ where: { accountId, status: { in: ["PENDING", "ACTIVE"] } } });
364	  if (n >= maxDatabases) throw new Error("Your plan's database limit is reached.");
365	}
366	
367	async function taskWordpressInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
368	  await assertDbCap(a.id, a.maxDatabases);
369	  const p = JSON.parse(payload || "{}") as { dbName?: string; dbUser?: string; dbPassEnc?: string; adminUser?: string; adminPassEnc?: string; adminEmail?: string };
370	  const dbName = String(p.dbName ?? "");
371	  const dbUser = String(p.dbUser ?? "");
372	  const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
373	  const adminUser = String(p.adminUser ?? "");
374	  const adminPass = (p.adminPassEnc ? decryptSecret(p.adminPassEnc) : "") ?? "";
375	  const adminEmail = String(p.adminEmail ?? "");
376	  if (!SAFE_ID.test(dbName) || !SAFE_ID.test(dbUser.slice(0, 32)) || !dbPass) throw new Error("invalid db identifiers");
377	  if (!/^[A-Za-z0-9_]{1,32}$/.test(adminUser) || !/^[A-Za-z0-9]{8,64}$/.test(adminPass) || !SAFE_EMAIL.test(adminEmail)) throw new Error("invalid admin identifiers");
378	  const u = a.username;
379	  const d = a.primaryDomain;
380	  if (!isValidUnixUsername(u) || !isValidHostingDomain(d)) throw new Error("unsafe account");
381	  const { webroot } = accountPaths(u);
382	
383	  await run(conn, "wp-cli", `command -v wp >/dev/null 2>&1 || (curl -fsSL https://raw.githubusercontent.com/wp-cli/builds/gh-pages/phar/wp-cli.phar -o /usr/local/bin/wp && chmod +x /usr/local/bin/wp)`);
384	  const sql = `CREATE DATABASE IF NOT EXISTS \\\`${dbName}\\\`; CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; GRANT ALL PRIVILEGES ON \\\`${dbName}\\\`.* TO '${dbUser}'@'localhost'; FLUSH PRIVILEGES;`;
385	  await run(conn, "wp db", `mysql -e "${sql}"`);
386	  const wp = `sudo -u ${u} -H wp --path=${webroot}`;
387	  await run(conn, "wp download", `${wp} core download --force`);
388	  await run(conn, "wp config", `${wp} config create --dbname=${dbName} --dbuser=${dbUser} --dbpass='${dbPass}' --force`);
389	  await run(conn, "wp install", `${wp} core install --url='https://${d}' --title='${d}' --admin_user='${adminUser}' --admin_password='${adminPass}' --admin_email='${adminEmail}' --skip-email`);
390	  await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
391	  // Shown ONCE in the panel, then the task result is cleared.
392	  return JSON.stringify({ adminUser, adminPassword: adminPass, url: `https://${d}/wp-admin/` });
393	}
394	
395	/**
396	 * One-click app catalog (beyond WordPress). Each recipe downloads the app into
397	 * the account webroot as the jailed user and, if it needs a database, creates a
398	 * scoped one — then the customer finishes the app's own web installer in the
399	 * browser (the standard shared-hosting "deploy, then set up" flow). WordPress
400	 * stays fully-automated via its own task; these are the download-and-configure
401	 * apps that have no clean CLI installer.
402	 */
403	const APP_RECIPES: Record<string, { name: string; url: string; strip: number; needsDb: boolean; note: string }> = {
404	  joomla: { name: "Joomla", url: "https://downloads.joomla.org/cms/joomla5/5-2-1/Joomla_5-2-1-Stable-Full_Package.tar.gz", strip: 0, needsDb: true, note: "Open your domain and complete the Joomla web installer with the database details above." },
