406	  phpbb: { name: "phpBB", url: "https://download.phpbb.com/pub/release/3.3/3.3.13/phpBB-3.3.13.tar.bz2", strip: 1, needsDb: true, note: "Open your domain/install and complete phpBB setup with the database details above, then delete the install/ folder." },
407	  matomo: { name: "Matomo Analytics", url: "https://builds.matomo.org/matomo.tar.gz", strip: 1, needsDb: true, note: "Open your domain and complete the Matomo setup wizard with the database details above." },
408	  grav: { name: "Grav CMS", url: "https://getgrav.org/download/core/grav/latest", strip: 1, needsDb: false, note: "Grav is flat-file — just open your domain. Admin plugin: bin/gpm install admin." },
409	};
