415	async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
416	  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
417	  const slug = String(p.slug ?? "");
418	  const recipe = APP_RECIPES[slug];
419	  if (!recipe) throw new Error("unknown app");
420	  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
421	  const u = a.username;
422	  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
423	  const { webroot } = accountPaths(u);
424	  const isBz2 = recipe.url.endsWith(".bz2");
425	  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
426	  // Download + extract into the webroot AS the account user (jailed).
427	  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
428	  let dbInfo = "";
429	  if (recipe.needsDb) {
430	    const dbName = String(p.dbName ?? "");
431	    const dbUser = String(p.dbUser ?? "");
432	    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
433	    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !dbPass) throw new Error("invalid db identifiers");
434	    const sql = `CREATE DATABASE IF NOT EXISTS \\\`${dbName}\\\`; CREATE USER IF NOT EXISTS '${dbUser}'@'localhost' IDENTIFIED BY '${dbPass}'; GRANT ALL PRIVILEGES ON \\\`${dbName}\\\`.* TO '${dbUser}'@'localhost'; FLUSH PRIVILEGES;`;
435	    await run(conn, "app db", `mysql -e "${sql}"`);
436	    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
437	    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
438	  }
439	  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
440	}
