442	/** Archive the account's home + DB dumps to a node-local backups dir.
443	 *
444	 * SECURITY (audit 2026-08-01, cross-tenant DB compromise): the DB dumps are
445	 * written to a ROOT-ONLY directory OUTSIDE the tenant's chroot and are NEVER
446	 * chowned to the tenant. The old code dumped into ${home}/.dbdump and chowned it
447	 * to the account user, so the tenant — who holds live SFTP creds chrooted to
448	 * ${home} — could race in and overwrite <db>.sql with arbitrary SQL that restore
449	 * later piped into `mysql` as root (a shared-node-wide GRANT/USE). Keeping the
450	 * dumps root-owned and off the tenant tree means the archived SQL is always our
451	 * own mysqldump output, never tenant-controlled. */
452	async function taskBackup(conn: Client, a: { id: string; username: string }, tsLabel: string): Promise<void> {
453	  const u = a.username;
454	  const dir = `/var/hosting-backups/${u}`;
455	  const dumpDir = `${dir}/dbdump`;
456	  const path = `${dir}/${tsLabel}.tar.gz`;
457	  // Root-only staging for the DB dumps; the whole dir is 700 root:root so the
458	  // tenant can neither read nor tamper with it.
459	  await run(
460	    conn,
461	    "dump dbs",
462	    `rm -rf ${dumpDir}; mkdir -p ${dumpDir}; chown -R root:root ${dir}; chmod 700 ${dir} ${dumpDir}; ` +
463	      `for dbn in $(mysql -N -e "SHOW DATABASES LIKE '${u}\\_%'" 2>/dev/null); do mysqldump "$dbn" > ${dumpDir}/"$dbn".sql 2>/dev/null; done`,
464	  );
465	  // One archive holding the home tree (${u}/…) and the root-owned dumps (dbdump/…).
466	  await run(conn, "tar home", `tar -czf ${path} -C /home ${u} -C ${dir} dbdump && rm -rf ${dumpDir}`);
467	  const st = await exec(conn, `stat -c %s ${path} 2>/dev/null || echo 0`);
468	  const sizeBytes = Math.max(0, Math.min(2_000_000_000, Number(st.out.trim()) || 0));
469	  await db.hostingBackup.create({ data: { accountId: a.id, path, sizeBytes } });
470	  // Retain the newest 5 per account; delete older files + rows.
471	  const all = await db.hostingBackup.findMany({ where: { accountId: a.id }, orderBy: { createdAt: "desc" } });
472	  for (const old of all.slice(5)) {
473	    await exec(conn, `rm -f ${old.path}`).catch(() => undefined);
474	    await db.hostingBackup.delete({ where: { id: old.id } }).catch(() => undefined);
475	  }
476	}
477	
478	/** Restore a backup over the account (destructive: overwrites files + DBs).
479	 *
480	 * The archive is extracted to a ROOT-ONLY staging dir (never straight into the
481	 * tenant's writable tree), and only DB dumps in THIS tenant's namespace
482	 * (`${u}_*.sql`) are replayed — so a restore can never touch another tenant's
483	 * database, and the SQL content is our own dump, not anything the tenant could
484	 * have planted (see taskBackup). */
485	async function taskRestore(conn: Client, a: { id: string; username: string }, payload: string | null): Promise<void> {
486	  const backupId = String(JSON.parse(payload || "{}").backupId ?? "");
487	  const b = await db.hostingBackup.findFirst({ where: { id: backupId, accountId: a.id } });
488	  if (!b) throw new Error("backup not found");
489	  const u = a.username;
490	  const { home } = accountPaths(u);
491	  if (!/^\/var\/hosting-backups\/[a-z0-9]+\/[A-Za-z0-9._-]+\.tar\.gz$/.test(b.path)) throw new Error("unsafe backup path");
492	  const stage = `/var/hosting-backups/${u}/.restore`;
493	  await run(conn, "extract", `rm -rf ${stage}; mkdir -p ${stage}; chown root:root ${stage}; chmod 700 ${stage}; tar -xzf ${b.path} -C ${stage}`);
494	  // Files: the archive root holds ${u}/… — copy it back over the home.
495	  await run(conn, "restore files", `[ -d ${stage}/${u} ] && cp -a ${stage}/${u}/. ${home}/ 2>/dev/null; true`);
496	  // DBs: replay ONLY dumps named for this tenant's own databases (${u}_*). The
497	  // shell `case` guard is belt-and-braces on top of the glob — a dump for
498	  // another tenant's DB is never fed to mysql.
499	  await run(
500	    conn,
501	    "restore dbs",
502	    `for f in ${stage}/dbdump/${u}_*.sql; do [ -f "$f" ] || continue; bn=$(basename "$f" .sql); ` +
503	      `case "$bn" in ${u}_*) mysql "$bn" < "$f" 2>/dev/null;; esac; done`,
504	  );
505	  await run(conn, "fix perms", `chown -R ${u}:${u} ${home}/public_html ${home}/tmp 2>/dev/null; rm -rf ${stage}; true`);
506	}
