508	async function processHostingTask(taskId: string): Promise<void> {
509	  const task = await db.hostingTask.findUnique({ where: { id: taskId }, include: { account: { include: { node: true } } } });
510	  if (!task || task.status !== "PENDING") return;
511	  await db.hostingTask.update({ where: { id: task.id }, data: { status: "RUNNING" } });
512	  const a = task.account;
513	  if (a.status !== "ACTIVE") { await failTask(task.id, "the account is not active"); return; }
514	  try {
515	    const conn = await connectNode(a.node);
516	    try {
517	      let result: string | null = null;
518	      if (task.kind === "PHP_SWITCH") await taskPhpSwitch(conn, a, task.payload);
519	      else if (task.kind === "WORDPRESS_INSTALL") result = await taskWordpressInstall(conn, a, task.payload);
520	      else if (task.kind === "APP_INSTALL") result = await taskAppInstall(conn, a, task.payload);
521	      else if (task.kind === "BACKUP") await taskBackup(conn, a, task.id);
522	      else if (task.kind === "RESTORE") await taskRestore(conn, a, task.payload);
523	      await db.hostingTask.update({ where: { id: task.id }, data: { status: "DONE", result, error: null } });
524	    } finally { try { conn.end(); } catch { /* */ } }
525	  } catch (e) {
526	    await failTask(task.id, (e instanceof Error ? e.message : String(e)).slice(0, 300));
527	  }
528	}
