530	export async function hostingTaskSweep(): Promise<void> {
531	  if (SANDBOX) {
532	    const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true, kind: true, account: { select: { primaryDomain: true } } }, take: 10 });
533	    for (const t of pend) {
534	      const result = t.kind === "WORDPRESS_INSTALL" ? JSON.stringify({ adminUser: "admin", adminPassword: "sandbox-demo-pw", url: `https://${t.account.primaryDomain}/wp-admin/` })
535	        : t.kind === "APP_INSTALL" ? JSON.stringify({ app: "App", url: `https://${t.account.primaryDomain}/`, note: "Sandbox: finish the installer in your browser." }) : null;
536	      await db.hostingTask.update({ where: { id: t.id }, data: { status: "DONE", result } });
537	      if (t.kind === "BACKUP") await db.hostingBackup.create({ data: { accountId: (await db.hostingTask.findUnique({ where: { id: t.id }, select: { accountId: true } }))!.accountId, path: `/var/hosting-backups/sandbox/${t.id}.tar.gz`, sizeBytes: 12_345_678 } }).catch(() => undefined);
538	    }
539	    return;
540	  }
541	  if (!ENABLED) return;
542	  const pend = await db.hostingTask.findMany({ where: { status: "PENDING" }, select: { id: true }, take: 5 });
543	  for (const t of pend) await processHostingTask(t.id).catch((e) => console.error(`[hosting] task ${t.id} failed`, e));
544	}
