32	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
33	  if (!nodes.length) return null;
34	  const loads = await Promise.all(
35	    nodes.map(async (n) => ({
36	      node: n,
37	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
38	    })),
39	  );
40	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
41	  return withRoom.length ? { id: withRoom[0].node.id } : null;
42	}
