441	export async function adminCreateHostingPlan(_prev: unknown, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
442	  await requireArea("fleet");
443	  const slug = String(formData.get("slug") ?? "").trim().toLowerCase();
444	  const name = String(formData.get("name") ?? "").trim();
445	  const priceCents = Math.round(Number(formData.get("priceCents") ?? 0));
446	  const diskGB = Math.round(Number(formData.get("diskGB") ?? 0));
447	  const maxSites = Math.round(Number(formData.get("maxSites") ?? 1));
448	  const maxDatabases = Math.round(Number(formData.get("maxDatabases") ?? 1));
449	  if (!/^[a-z][a-z0-9-]{1,31}$/.test(slug)) return { error: "Slug: lowercase letters, digits, dashes." };
450	  if (!name) return { error: "Enter a plan name." };
451	  if (priceCents < 0 || diskGB < 1) return { error: "Price and disk must be positive." };
452	  if (await db.hostingPlan.findUnique({ where: { slug } })) return { error: "A plan with that slug exists." };
