import { test } from "node:test";
import assert from "node:assert/strict";
import {
  isValidHostingDomain,
  normalizeHostingDomain,
  deriveUsername,
  isValidUnixUsername,
  planLimits,
  diskQuotaBlocks,
  pointToRecords,
  accountPaths,
} from "../lib/hosting.ts";

/* ------------------------------------------------------------------ *
 * Shared hosting is multi-tenant: these values end up in shell + nginx
 * on a box other customers share, so "provably well-formed" is a
 * security property, not a nicety.
 * ------------------------------------------------------------------ */

test("hosting domains: valid FQDNs pass, junk/injection is rejected", () => {
  for (const ok of ["example.com", "sub.example.co.uk", "my-site.io"]) assert.equal(isValidHostingDomain(ok), true, ok);
  for (const bad of ["", "no-tld", "http://x.com", "a b.com", "x.com/../y", "x.com;rm -rf", "*.x.com"]) {
    assert.equal(isValidHostingDomain(bad), false, bad);
  }
});

test("normalizeHostingDomain strips scheme-less www + trailing dot + case", () => {
  assert.equal(normalizeHostingDomain("WWW.Example.com."), "example.com");
});

test("derived usernames are always shell-inert Linux usernames", () => {
  const cases: [string, string][] = [
    ["alice", "cms01abc"],
    ["9startswithnum", "id123456"],
    ["a.b+c@d", "xyz"],
    ["", ""],
    ["VeryLongLocalPartThatExceedsLimits", "cms0zzzzzz"],
  ];
  for (const [seed, dis] of cases) {
    const u = deriveUsername(seed, dis);
    assert.equal(isValidUnixUsername(u), true, `${seed}/${dis} -> ${u}`);
    assert.ok(u.length <= 16 && /^[a-z]/.test(u), u);
  }
});

test("isValidUnixUsername rejects anything a shell could interpret", () => {
  assert.equal(isValidUnixUsername("nxalice"), true);
  for (const bad of ["Alice", "9user", "a b", "root;rm", "us$er", "ab", "toolongusernameoverthirtytwochars_padding"]) {
    assert.equal(isValidUnixUsername(bad), false, bad);
  }
});

test("planLimits sanitises + defaults PHP versions", () => {
  const l = planLimits({ diskGB: 10, maxSites: 3, maxDatabases: 2, bandwidthTB: 1, phpVersions: "8.1, 8.3 , junk" });
  assert.deepEqual(l.phpVersions, ["8.1", "8.3"]);
  assert.equal(l.diskGB, 10);
  const bad = planLimits({ diskGB: 0, maxSites: 0, maxDatabases: -1, bandwidthTB: -5, phpVersions: "" });
  assert.equal(bad.diskGB, 1);
  assert.equal(bad.maxSites, 1);
  assert.equal(bad.maxDatabases, 0);
